examples.template:
Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
    Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
        MonarchButton(onClick = { page = maxOf(1, page - 1) }, variant = MonarchButtonVariant.Ghost, size = MonarchButtonSize.Sm) {
            MonarchIcon(SampleIcons.ChevronLeft, "Previous page")
        }
        pageButton({{full.items.0}})
        MonarchText(text = {{full.items.1}})
        pageButton({{full.items.2}})
        pageButton({{full.items.3}})
        pageButton({{full.items.4}})
        MonarchText(text = {{full.items.5}})
        pageButton({{full.items.6}})
        MonarchButton(onClick = { page = minOf({{full.pageCount}}, page + 1) }, variant = MonarchButtonVariant.Ghost, size = MonarchButtonSize.Sm) {
            MonarchIcon(SampleIcons.ChevronRight, "Next page")
        }
    }
    Row(
        modifier = Modifier.semantics {
            contentDescription = {{compact.label}}
            stateDescription = "Page $page of {{compact.pageCount}}"
        },
        horizontalArrangement = Arrangement.spacedBy(4.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchText(text = {{compact.range}})
        MonarchButton(onClick = { page = maxOf(1, page - 1) }, enabled = page > 1, variant = MonarchButtonVariant.Ghost, size = MonarchButtonSize.Sm) {
            MonarchIcon(SampleIcons.ChevronLeft, "Previous page")
        }
        MonarchButton(onClick = { page += 1 }, enabled = page * {{compact.pageSize}} < {{compact.totalItems}}, variant = MonarchButtonVariant.Ghost, size = MonarchButtonSize.Sm) {
            MonarchIcon(SampleIcons.ChevronRight, "Next page")
        }
    }
}

examples.setupTemplate:
var page by remember { mutableIntStateOf({{page}}) }
val pageButton: @Composable (String) -> Unit = { label ->
    MonarchButton(
        text = label,
        onClick = { page = label.toIntOrNull() ?: page },
        variant = if (page.toString() == label) MonarchButtonVariant.Secondary else MonarchButtonVariant.Ghost,
        size = MonarchButtonSize.Sm,
    )
}

